{"filePath": "/Users/dwahl/Scripts/pantoken/tools/translation-adapters/src/index.ts", "newString": "/**
 * True when `translated` is just `source` echoed back (trimmed, case-insensitive) — the shape a
 * silently-failing AI adapter tends to produce: it exits 0 with syntactically valid JSON, so nothing
 * else flags the run as unhealthy.
 */
export function isPassthroughTranslation(source: string, translated: string): boolean {
  return source.trim().toLowerCase() === translated.trim().toLowerCase();
}

/**
 * Reserved key a `src/i18n.json` source file can use to list its own `verbatimKeys` (see
 * {@link I18nTranslationOptions.verbatimKeys}) alongside its translatable strings, so the
 * passthrough guard's allowlist travels with the source content instead of being hardcoded
 * separately in every translate script.
 */
export const VERBATIM_MARKER_KEY = "$verbatim";

/**
 * Split a raw `src/i18n.json`-shaped object into its translatable strings and its
 * `$verbatim` marker list (dropped from `strings`, defaulting to `[]` when absent or malformed).
 */
export function splitVerbatimMarker(raw: Record<string, unknown>): {
  strings: Record<string, string>;
  verbatimKeys: string[];
} {
  const strings: Record<string, string> = {};
  let verbatimKeys: string[] = [];
  for (const [key, value] of Object.entries(raw)) {
    if (key === VERBATIM_MARKER_KEY) {
      if (Array.isArray(value)) {
        verbatimKeys = value.filter((v): v is string => typeof v === "string");
      }
      continue;
    }
    if (typeof value === "string") strings[key] = value;
  }
  return { strings, verbatimKeys };
}

